  t.target_hr_high,
  t.target_zone_ids,
  t.rationale,
  t.gate_action,
  t.status,
  t.activity_log_id,
  t.created_at,
  t.updated_at,
  t.deleted_at
FROM public.prescribed_runs t
WHERE t.user_id = 'fe481797-4114-4f59-824d-223e0281823e';

CREATE VIEW claude_ro.program_phases AS
