  t.secondary_style_id,
  t.phase_set_id
FROM public.program_phases t
WHERE EXISTS (SELECT 1 FROM public.phase_sets ps WHERE ps.id = t.phase_set_id AND ps.user_id = 'fe481797-4114-4f59-824d-223e0281823e') OR EXISTS (SELECT 1 FROM public.programs p WHERE p.id = t.program_id AND p.user_id = 'fe481797-4114-4f59-824d-223e0281823e');

CREATE VIEW claude_ro.program_sessions AS
