DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'claude_readonly') THEN
    EXECUTE 'GRANT USAGE ON SCHEMA claude_ro TO claude_readonly';
    EXECUTE 'GRANT SELECT ON ALL TABLES IN SCHEMA claude_ro TO claude_readonly';
    EXECUTE 'ALTER ROLE claude_readonly SET search_path = claude_ro';
  END IF;
END $$;
